#!/bin/bash
set -e
cd avbox

echo "=== 修复 Android 12+ 启动图标 ==="

# 1. 把 Hello 图写入为 splash_icon_hello
echo "" | base64 -d > app/src/main/res/drawable/splash_icon_hello.webp
echo "Hello splash 图标已写入"

# 2. 修改 values-v31/styles.xml，把 windowSplashScreenAnimatedIcon 指向 Hello
python3 << 'PYEOF2'
import re
p = "app/src/main/res/values-v31/styles.xml"
with open(p, "r", encoding="utf-8") as f:
    content = f.read()
print("修改前:")
print(content)
# 替换 splash_icon_avbox 为 splash_icon_hello
new_content = content.replace("@drawable/splash_icon_avbox", "@drawable/splash_icon_hello")
with open(p, "w", encoding="utf-8") as f:
    f.write(new_content)
print("修改后:")
print(new_content)
PYEOF2

echo "=== Android 12+ 启动图标修复完成 ==="